import React from 'react'

export default function About(props) {
  //  const[myStyle,setMyStyle]=useState({
  //       color:'black',
  //       backgroundColor:'white'
  //   })
  let myStyle={
    color:props.mode==='dark'?'white':'#042743',
    backgroundColor:props.mode==='dark'?'rgb(36 74 104)':'white'
  }


  return (
    <div className="container" style={myStyle}>
        <h4 className="my-4" style={{ color:props.mode==='dark'?'white':'#042743'}}>About Us</h4>
      <div className="accordion" id="accordionExample" style={myStyle}>
  <div className="accordion-item">
    <h2 className="accordion-header">
      <button className="accordion-button" style={myStyle} type="button" data-bs-toggle="collapse" data-bs-target="#collapseOne" aria-expanded="true" aria-controls="collapseOne">
      <strong> Analyze Your Text</strong>
      </button>
    </h2>
    <div id="collapseOne" className="accordion-collapse collapse show" data-bs-parent="#accordionExample">
      <div className="accordion-body" style={myStyle}>
         With TextUtils, you can easily analyze and manipulate your text. You can convert your text to uppercase or lowercase, making it ideal for formatting tasks. If you need to copy the modified text, you can do so with a simple click. Additionally, if you make any changes and want to revert, you have an undo feature to quickly restore the text to its original state. These features combine to make your text analysis fast and convenient.
      </div>
    </div>
  </div>
  <div className="accordion-item">
    <h2 className="accordion-header">
      <button className="accordion-button collapsed" style={myStyle} type="button" data-bs-toggle="collapse" data-bs-target="#collapseTwo" aria-expanded="false" aria-controls="collapseTwo">
      <strong> Free To Use</strong>
      </button>
    </h2>
    <div id="collapseTwo" className="accordion-collapse collapse" data-bs-parent="#accordionExample">
      <div className="accordion-body" style={myStyle}>
        TextUtils is completely free to use! No sign-up, no payments, just enter your text and analyze it immediately. Our goal is to provide easy and accessible text analysis tools for everyone. 
      </div>
    </div>
  </div>
  <div className="accordion-item">
    <h2 className="accordion-header">
      <button className="accordion-button collapsed" style={myStyle} type="button" data-bs-toggle="collapse" data-bs-target="#collapseThree" aria-expanded="false" aria-controls="collapseThree">
      <strong> Browser Compatible </strong>
      </button>
    </h2>
    <div id="collapseThree" className="accordion-collapse collapse" data-bs-parent="#accordionExample">
      <div className="accordion-body" style={myStyle}>
         Whether you're on Chrome, Firefox, or Safari, TextUtils works smoothly across all modern browsers. Just open your browser and start analyzing text without any hassles.
      </div>
    </div>
  </div>
</div>
    </div>
  )
}
