import React, {useState} from 'react'

export default function TextForm(props) {
    const handleUpClick=()=>{
        prevSetText(text);
        // console.log("UpperCase was Clicked" +text);
        let newText=text.toUpperCase();
        setText(newText)
        props.showAlert("Converted to UpperCase!", "success");

    }
    const handleLoClick=()=>{
        prevSetText(text);
        let newText=text.toLowerCase();
        setText(newText)
        props.showAlert("Converted to LowerCase!", "success");

    }
    const handleClClick=()=>{
        prevSetText(text);
        let newText="";
        setText(newText)
        props.showAlert("Text Cleared!", "success");

    }
    const handleOnChange=(event)=>{
        console.log("On Change");
        setText(event.target.value);
    }
    const handleUndoClick=()=>{
        setText(prevText);
        props.showAlert("Undo Performed!", "success");
    }
    const handleCopyClick=()=>
    {
        navigator.clipboard.writeText(text);
        document.getSelection().removeAllRanges();
        props.showAlert("Copied to Clipboard!", "success");
    }
    const[text, setText]=useState("");
    const[prevText,prevSetText]=useState("");
  return (
    <>
    <div className="container" style={{color:props.mode==='dark'?'white':'#042743'}}>
         <h5>{props.heading}</h5>
          <div className="mb-3">
          <textarea className="form-control" value={text}  onChange={handleOnChange} style={{backgroundColor:props.mode==='dark'?'#13466e':'white',color:props.mode==='dark'?'white':'#042743'}} id="myBox" rows="8"></textarea>
          </div>
          <button disabled={text.length===0} className="btn btn-primary mx-2 my-2" onClick={handleUpClick}>Convert To UpperCase</button>
          <button disabled={text.length===0} className="btn btn-primary mx-2 my-2" onClick={handleLoClick}>Convert To LowerCase</button>
          <button disabled={text.length===0} className="btn btn-primary mx-2 my-2" onClick={handleClClick}>Clear Text</button>
          <button disabled={text.length===0} className="btn btn-primary mx-2 my-2" onClick={handleUndoClick}>Undo</button>
          <button disabled={text.length===0} className="btn btn-primary mx-2 my-2" onClick={handleCopyClick}>Copy Text</button>

    </div>
    <div className="container my-3" style={{color:props.mode==='dark'?'white':'#042743'}}>
        <h5> Your Text Summary</h5>
        <p> {text.split(/\s+/ ).filter((element)=>{return element.length!==0}).length} Words and {text.length} Characters</p>
        <p>{0.008 * text.split(" ").filter((element)=>{return element.length!==0}).length} Minutes Read</p>
        <h6>Preview</h6>
        <p>{text.length>0?text:'Nothing to Preview!'}</p>
    </div>
    </>
  )
}
